use crate::semantic_delta::SemanticDelta;
use crate::dependency::PropagationTrace;
use crate::repair_regions::RepairRegion;
use serde::{Deserialize, Serialize};

/// Per-edit metrics collected during the incremental recomputation pipeline.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct EditMetrics {
    /// Human-edited tokens (tokens changed by the human)
    pub human_edit_tokens: usize,
    /// Tokens marked stale after delta propagation
    pub stale_tokens: usize,
    /// Tokens regenerated by workers
    pub regenerated_tokens: usize,
    /// Tokens left untouched (UNAFFECTED)
    pub untouched_tokens: usize,
    /// Tokens generated by strong model
    pub strong_model_tokens: usize,
    /// Tokens generated by cheap model
    pub cheap_model_tokens: usize,
    /// Number of affected semantic nodes (state != UNAFFECTED)
    pub affected_semantic_nodes: usize,
    /// Total repair latency in milliseconds
    pub repair_latency_ms: u64,
    /// Number of repair regions selected
    pub repair_regions_count: usize,
    /// Propagation depth (max hops from source)
    pub max_dependency_depth: usize,
    /// Edit waste: unnecessary changed tokens / all changed tokens
    pub edit_waste: f32,
    /// Repair precision: correctly modified affected units / all modified units
    pub repair_precision: f32,
    /// Repair recall: correctly repaired affected units / all truly affected units
    pub repair_recall: f32,
    /// Semantic locality: 1 - regenerated/total tokens
    pub semantic_locality: f32,
    /// Strong compute fraction: strong-model tokens / total generated tokens
    pub strong_compute_fraction: f32,
}

impl EditMetrics {
    /// Create new metrics from a human edit.
    pub fn from_edit(
        human_edit_tokens: usize,
        total_document_tokens: usize,
        affected: &[(String, f32, PropagationTrace)],
        regions: &[RepairRegion],
        repair_results: &[crate::orchestration::RepairResult],
        delta: &SemanticDelta,
    ) -> Self {
        let regenerated: usize = repair_results.iter().map(|r| {
            // Rough estimate: length of repaired text
            r.repaired_text.split_whitespace().count()
        }).sum();

        let stale = affected
            .iter()
            .filter(|(_, score, _)| *score > 0.15 && *score <= 0.7)
            .count();

        let untouched = affected
            .iter()
            .filter(|(_, score, _)| *score <= 0.15)
            .count();

        let affected_nodes = affected
            .iter()
            .filter(|(_, score, _)| *score > 0.15)
            .count();

        let cheap_tokens: usize = repair_results
            .iter()
            .filter(|r| r.worker_id == "cheap_ar")
            .map(|r| r.repaired_text.split_whitespace().count())
            .sum();

        let strong_tokens: usize = repair_results
            .iter()
            .filter(|r| r.worker_id == "strong_model")
            .map(|r| r.repaired_text.split_whitespace().count())
            .sum();

        let edit_waste = if regenerated > 0 {
            // Estimate: proportion of regenerated tokens that were "unnecessary"
            // (for demo, assume 10% waste)
            0.1
        } else {
            0.0
        };

        let repair_precision = if regenerated + stale + untouched > 0 {
            // Placeholder: proportion of correct repairs
            0.85
        } else {
            1.0
        };

        let repair_recall = if affected_nodes > 0 {
            // Proportion of truly affected nodes that were repaired
            let repaired = repair_results.len();
            repaired as f32 / affected_nodes as f32
        } else {
            1.0
        };

        let semantic_locality = if total_document_tokens > 0 {
            1.0 - (regenerated as f32 / total_document_tokens as f32)
        } else {
            1.0
        };

        let strong_compute_fraction = if regenerated + cheap_tokens + strong_tokens > 0 {
            strong_tokens as f32 / (regenerated + cheap_tokens + strong_tokens) as f32
        } else {
            0.0
        };

        Self {
            cheap_model_tokens: cheap_tokens,
            strong_model_tokens: strong_tokens,
            human_edit_tokens,
            stale_tokens: stale,
            regenerated_tokens: regenerated,
            untouched_tokens: untouched,
            affected_semantic_nodes: affected_nodes,
            repair_latency_ms: 0, // will be set by caller
            repair_regions_count: regions.len(),
            max_dependency_depth: affected
                .iter()
                .map(|(_, _, trace)| trace.decayed_score.floor() as usize)
                .max()
                .unwrap_or(0),
            edit_waste,
            repair_precision,
            repair_recall,
            semantic_locality,
            strong_compute_fraction,
        }
    }

    /// Record repair latency.
    pub fn with_latency(mut self, latency_ms: u64) -> Self {
        self.repair_latency_ms = latency_ms;
        self
    }

    /// Human-friendly display format.
    pub fn display(&self) -> String {
        format!(
            "Document length:       {} tokens\n\
             Human edit:               {} tokens\n\
             Affected region:         {} tokens\n\
             Strong-model output:      {} tokens\n\
             Cheap-model output:      {} tokens\n\
             Untouched text:         {} tokens\n",
            self.total_document_tokens(),
            self.human_edit_tokens,
            self.affected_region_tokens(),
            self.strong_model_tokens,
            self.cheap_model_tokens,
            self.untouched_tokens,
        )
    }

    fn total_document_tokens(&self) -> usize {
        self.human_edit_tokens + self.stale_tokens + self.regenerated_tokens + self.untouched_tokens
    }

    fn affected_region_tokens(&self) -> usize {
        self.stale_tokens + self.regenerated_tokens
    }
}

/// Debugging dashboard state for a single edit operation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DebugDashboard {
    /// The edit that was performed
    pub edit: EditSnapshot,
    /// Propagation results
    pub propagation: PropagationSnapshot,
    /// Repair regions selected
    pub regions: Vec<RepairRegionSnapshot>,
    /// Worker routing decisions
    pub routing: Vec<RoutingDecision>,
    /// Verification results
    pub verification: Option<VerificationSnapshot>,
    /// Full pipeline metrics
    pub metrics: EditMetrics,
}

/// Snapshot of the human edit.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EditSnapshot {
    /// Original text
    pub original: String,
    /// New text
    pub new_text: String,
    /// Tokens changed
    pub tokens_changed: usize,
    /// Delta confidence
    pub delta_confidence: f32,
    /// Delta semantic distance
    pub semantic_distance: f32,
}

/// Snapshot of propagation results.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PropagationSnapshot {
    /// Nodes inspected
    pub nodes_inspected: usize,
    /// Nodes affected
    pub nodes_affected: usize,
    /// Max dependency depth
    pub max_dependency_depth: usize,
    /// Per-node affectedness
    pub affectedness: Vec<(String, f32, String)>,
}

/// Snapshot of a repair region.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RepairRegionSnapshot {
    /// Affected node IDs
    pub affected_nodes: Vec<String>,
    /// Estimated complexity
    pub estimated_complexity: f32,
    /// Worker assigned
    pub worker_assigned: String,
    /// Whether verified
    pub verified: bool,
}

/// Routing decision for a repair region.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RoutingDecision {
    /// Region ID (index)
    pub region_index: usize,
    /// Chosen worker
    pub worker: String,
    /// Heaviness score
    pub heaviness: f32,
    /// Expected quality
    pub expected_quality: f32,
    /// Estimated latency
    pub estimated_latency_ms: u64,
}

/// Verification snapshot.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VerificationSnapshot {
    /// Whether all checks passed
    pub passed: bool,
    /// Check details
    pub checks: Vec<(String, bool, String)>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::semantic_delta::{self, QuantityDirection};

    #[test]
    fn test_metrics_creation() {
        let mut graph = crate::dependency::DependencyGraph::new();
        graph.add_edge(crate::dependency::DependencyEdge::new(
            "s1".to_string(),
            "s2".to_string(),
            physis_core::relation::RelationType::DependsOn,
            0.8,
            0.9,
        ));

        let delta = semantic_delta::SemanticDelta {
            source_node: "s1".to_string(),
            lexical: semantic_delta::LexicalDiff::no_change(),
            proposition_changed: true,
            scope_change: Some(semantic_delta::ScopeDelta::Narrowed),
            polarity_change: None,
            quantity_change: Some(semantic_delta::QuantityDelta {
                old_value: 18.0,
                new_value: 3.0,
                direction: QuantityDirection::Decrease,
            }),
            modality_change: None,
            entity_changes: vec![],
            relation_changes: vec![],
            old_claims: vec!["accuracy 18%".to_string()],
            new_claims: vec!["accuracy 3%".to_string()],
            removed_constraints: vec![],
            added_constraints: vec![],
            semantic_distance: 0.8,
            confidence: 0.9,
        };

        let affected = vec![
            ("s2".to_string(), 0.75, PropagationTrace {
                source: "s1".to_string(),
                target: "s2".to_string(),
                relation: physis_core::relation::RelationType::DependsOn,
                incoming_score: 1.0,
                relation_relevance: 0.8,
                scope_overlap: 0.6,
                resulting_score: 0.75,
                decayed_score: 0.525,
            }),
            ("s3".to_string(), 0.45, PropagationTrace {
                source: "s1".to_string(),
                target: "s3".to_string(),
                relation: physis_core::relation::RelationType::Supports,
                incoming_score: 0.7,
                relation_relevance: 0.5,
                scope_overlap: 0.4,
                resulting_score: 0.45,
                decayed_score: 0.315,
            }),
        ];

        let regions = vec![];

        let repair_results = vec![];

        let metrics = EditMetrics::from_edit(
            11, // human edit tokens
            8420, // total document tokens
            &affected,
            &regions,
            &repair_results,
            &delta,
        );

        assert!(metrics.human_edit_tokens == 11);
        assert!(metrics.affected_semantic_nodes > 0);
        assert!(metrics.semantic_locality > 0.0);
        assert!(metrics.strong_compute_fraction >= 0.0);
    }

    #[test]
    fn test_metrics_display() {
        let mut graph = crate::dependency::DependencyGraph::new();
        graph.add_edge(crate::dependency::DependencyEdge::new(
            "s1".to_string(),
            "s2".to_string(),
            physis_core::relation::RelationType::DependsOn,
            0.8,
            0.9,
        ));

        let delta = semantic_delta::SemanticDelta::no_semantic_change(
            "s1".to_string(),
            "old text",
            "old text",
        );

        let affected: Vec<(String, f32, PropagationTrace)> = vec![];
        let regions = vec![];
        let repair_results = vec![];

        let metrics = EditMetrics::from_edit(
            11,
            8420,
            &affected,
            &regions,
            &repair_results,
            &delta,
        );

        let display = metrics.display();
        assert!(display.contains("tokens"));
    }
}